#!/usr/bin/env python3
"""Machine-prefill implementation_plan.json — every deterministic field is
computed here so the model only fills the judgment fields listed in
`modelFields` (measured 4-8 min of model time per page was spent restating
counts a script can derive).

The model replaces each "__MODEL__" placeholder in place, then runs
check_implementation_plan.py (which fails while any placeholder remains).
"""

from __future__ import annotations

import argparse
from pathlib import Path

from common import dump_json, load_json
from summarize_spec_artifacts import build_digest

MODEL_TODO = "__MODEL__"

IMAGE_IMPL = {"image", "image_png", "image_webp", "image_fill", "svg", "asset"}
SHAPE_IMPL = {"shape", "oval_shape", "gradient_shape", "vector_shape", "shape_container"}
COVERED_IMPL = {"covered_by_asset", "covered_by_text", "covered_by_shared_component", "hidden"}


def center_in(bbox: list, region: list) -> bool:
    if not (isinstance(bbox, list) and isinstance(region, list) and len(bbox) == 4 and len(region) == 4):
        return False
    cx, cy = bbox[0] + bbox[2] / 2, bbox[1] + bbox[3] / 2
    return region[0] <= cx <= region[0] + region[2] and region[1] <= cy <= region[1] + region[3]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--spec-dir", required=True)
    parser.add_argument("--project-root", default=".")
    parser.add_argument("--out", help="default <spec-dir>/implementation_plan.json")
    parser.add_argument("--force", action="store_true", help="overwrite an existing plan")
    args = parser.parse_args()

    spec_dir = Path(args.spec_dir).expanduser().resolve()
    out = Path(args.out) if args.out else spec_dir / "implementation_plan.json"
    if out.is_file() and not args.force:
        raise SystemExit(f"ERROR: {out} already exists; pass --force to re-prefill")

    digest = build_digest(spec_dir)
    render_plan = load_json(spec_dir / "render_plan.json")
    layout = load_json(spec_dir / "layout_contract.json")
    nodes = render_plan.get("nodes") or {}

    by_impl = (digest.get("renderPlan") or {}).get("byImplementation") or {}
    counts = {
        "requiredVisibleNodeCount": (digest.get("renderPlan") or {}).get("requiredVisibleNodeCount"),
        "textNodeCount": by_impl.get("text", 0),
        "imageNodeCount": sum(v for k, v in by_impl.items() if k in IMAGE_IMPL),
        "shapeNodeCount": sum(v for k, v in by_impl.items() if k in SHAPE_IMPL),
        "assetAtomicNodes": sum(v for k, v in by_impl.items() if k in {"image", "image_png", "image_webp", "svg", "asset"}),
        "coveredNodes": sum(v for k, v in by_impl.items() if k in COVERED_IMPL),
        "renderImplementationTypes": sorted(by_impl),
    }

    # Assign every required visible node to the layout region containing its center.
    regions = []
    assigned: set[str] = set()
    for comp_name, comp in layout.items():
        if not isinstance(comp, dict):
            continue
        region_bbox = comp.get("bbox")
        members: dict[str, list[str]] = {}
        for node_id, item in nodes.items():
            if not item.get("required") or node_id in assigned:
                continue
            if center_in(item.get("bbox"), region_bbox):
                members.setdefault(item.get("implementation") or "unknown", []).append(node_id)
                assigned.add(node_id)
        regions.append({
            "region": comp_name,
            "bbox": region_bbox,
            "nodeCountByImplementation": {k: len(v) for k, v in sorted(members.items())},
            "mustImplementNodes": sorted(n for v in members.values() for n in v),
            "mergeOrSkipRationale": MODEL_TODO,
        })
    unassigned = sorted(n for n, item in nodes.items() if item.get("required") and n not in assigned)
    if unassigned:
        regions.append({"region": "_unassigned", "bbox": None,
                        "nodeCountByImplementation": {}, "mustImplementNodes": unassigned,
                        "mergeOrSkipRationale": MODEL_TODO})

    plan = {
        "prefilledBy": "prefill_implementation_plan.py",
        "artifactInventory": digest.get("artifacts"),
        "designAlignment": {
            "sourceSchema": (digest.get("scene") or {}).get("sourceSchema"),
            "artboard": (digest.get("scene") or {}).get("artboard"),
            "classification": digest.get("classification"),
            **counts,
            "coordinateRenderStrategy":
                "single scaled artboard Stack; render_plan bboxes are the only visible-layer "
                "coordinate source; visible dart generated by generate_canvas.py (step 6.7), never hand-written",
            "sharedComponents": (digest.get("renderPlan") or {}).get("sharedComponents") or [],
            "nodeCoveragePlan": regions,
        },
        "projectAlignment": {
            "entrypoint": MODEL_TODO,
            "appShell": MODEL_TODO,
            "existingFeatureDirs": MODEL_TODO,
            "missingFeatureDirs": MODEL_TODO,
            "fanoutOwnedFiles": MODEL_TODO,
            "faninRequests": MODEL_TODO,
        },
        "fixtureAlignment": {
            "fixtureSource": MODEL_TODO,
            "states": ((digest.get("classification") or {}).get("states")),
            "stateData": MODEL_TODO,
        },
        "interactionCaseScope": (digest.get("interactionTestPlan") or {}).get("caseIds"),
        "traceAndRepair": {
            "implementationMap": "map every required render_plan node; renderMode absolute_positioned",
            "traceStrategy": "gen_layout_trace_test.py on merged_expected.json against the real online page",
            "screenshotCommand": "device_lock.py acquire -> capture_runtime_screenshot.py -> device_lock.py release",
            "diffCommand": "visual_diff.py + make_repair_plan.py",
            "singleRepairBudget": 1,
            "postRepairRecord": "post_repair_diff_report.json + visual_report.md",
        },
        "forbiddenShortcuts": [
            "full design/reference image as background or visible layer",
            "actual derived from reference",
            "Material default icons / placeholder boxes for exported assets",
            "tests inventing their own data instead of the shared fixture",
            "parallel edits to shared files (pubspec/routes/DI/codegen)",
            "whole-file reads of scene.json/render_plan.json/layout_contract.json/repair_plan.json/oas.json/oas_ref_resources.json",
        ],
        "modelFields": [
            "projectAlignment.*",
            "fixtureAlignment.fixtureSource",
            "fixtureAlignment.stateData",
            "designAlignment.nodeCoveragePlan[*].mergeOrSkipRationale",
        ],
    }
    dump_json(plan, out)
    filled = sum(1 for r in regions for _ in r["mustImplementNodes"])
    print(f"ok prefilled {out} ({len(regions)} regions, {filled} required nodes assigned; "
          f"model fills: {', '.join(plan['modelFields'])})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
